//和假贺老四对话

	If ($Clue == 0) @Talkhelaosi0;
	If ($Clue == 15) @Talkhelaosi15;
	If ($Clue == 20) @Talkhelaosi20;
	If ($Clue == 25) @Talkhelaosi20;
	If ($Clue == 45) @Talkhelaosi45;
	
	Say("贺老四：属下暂时没有什么消息。", 0);
	Return;
	
@Talkhelaosi0:
	Say("贺老四：两位怎么随便就闯进来，再不走，我贺老四可就不客气了。", 0);
	Return;
	
@Talkhelaosi15:
	Say("贺老四：两位怎么随便就闯进来，我贺老四最不喜欢有人骚扰。", 0);
	SetNpcKind("杨瑛", 1);
	NpcGotoEx("杨瑛", 3, 18);
	PlayerGoto(2, 17);
	SetPlayerDir(5);
	SetNpcDir("杨瑛", 4);
	Say("杨瑛：天王盖地虎——", 39);
	Say("贺老四：——大圣镇番妖。阁下喝得是哪条河的水？", 0);
	Say("杨瑛：湖纳百川皆我饮，高声一喝楚天晴。", 39);
	Say("贺老四：啊，原来是帮主大驾亲临！请帮主恕罪，帮主换回女装，属下一时眼拙，没有认出来……", 0);
	Say("杨瑛：不必多礼。我此次入川乃是机密，你当然不知。目下，我正在找一对姓张的兄妹，二十上下，京城口音，你最近见到过吗？", 39);
	Say("贺老四：属下的确见到一男一女，和帮主描述的相似——前天傍晚，他们就在客栈投宿。", 0);
	Say("杨瑛：奇怪……客栈的小二和掌柜怎么却说没有……", 39);
	Say("贺老四：这……属下就不知道了。不过，客栈的房间里说不定会留有什么线索。 ", 0);
	Say("杨瑛：那好。如果有什么新的消息，马上禀告我。独孤大哥，我们再去客栈看看。", 39);
	SetNpcKind("杨瑛", 3);
	Assign($Clue, 20);
	Memo("暗舵的贺老四告诉杨瑛，他看见张如梦兄妹在客栈出现过，两人觉得应该再去调查。");
	Return;
	
@Talkhelaosi20:
	Say("贺老四：属下暂时没有什么消息。帮主不妨再去客栈看看。", 0);
	Return;
	
@Talkhelaosi45:
	Say("贺老四：帮主还有什么吩咐？", 0);
	Say("杨瑛：贺老四，本帮朱后使说，上个月他在成都购置了一批蜀锦存放在你这里，你交给索七带回总堂吧。", 39);
	Say("贺老四：呃……对的、对的，属下差点忘了……属下这就去办。", 0);
	NpcGoto("贺老四",3,21);
	SetPlayerDir(0);
	SetNpcDir("杨瑛",0);
	Watch("杨瑛", "贺老四", 0);
	Say("杨瑛：慢着！你要去哪？", 39);
	Say("贺老四：属，属下去取朱后使留下的货色……", 0);
	Say("杨瑛：天王帮从来没有什么朱后使，也从来没在成都买过蜀锦，你到何处去取……", 43);
	Say("果然是个假冒的！",43);
	Say("贺老四：帮主说笑了，属下……", 0);
	Say("贺老四：去死吧！", 0);
	Say("独孤剑：小心！", 6);
	Assign($Clue, 46);
	SetNpcRelation("贺老四",1);
	Return;

scripts.贺老四死亡.txt:
//假贺老四死亡

	FadeOut();
	ClearEffect();
	FadeIn();
	Sleep(1500);
	Say("杨瑛：糟了，他死了！", 42);
	Say("独孤剑：线索又断了！可恶，五色教尽是些卑鄙无耻之徒，只敢躲在背后暗箭伤人……", 5);
	Say("杨瑛：事情也许不至于这么糟……独孤大哥，我们在这里搜一搜，或许有些线索。", 39);
	Say("独孤剑：嗯！", 1);
	Assign($Clue, 50);
	Memo("杨瑛设计诱假贺老四露出真面目，不料未来得及追问，假贺老四却服毒自尽。");
	SetMapTrap(01,"trap01.txt");
	SetMapTrap(02,"trap02.txt");
	Return;

scripts.杨瑛的同伴对话.txt:
//和杨瑛的同伴对话

	If ($Clue == 0) @Clue0;
	If ($Clue == 10) @Clue10;
	If ($Clue == 15) @Clue15;
	If ($Clue == 20) @Clue20;
	If ($Clue == 25) @Clue25;
	If ($Clue == 30) @Clue30;
	If ($Clue == 31) @Clue31;
	If ($Clue == 35) @Clue35;
	If ($Clue == 40) @Clue40;
	If ($Clue == 41) @Clue41;
	If ($Clue == 45) @Clue45;
	If ($Clue == 46) @Clue46;
	If ($Clue == 50) @Clue50;
	If ($Clue == 60) @Clue60;
	If ($Clue == 65) @Clue65;
	If ($Clue == 70) @Clue70;
	If ($Clue == 71) @Clue71;
	If ($Clue >= 75) @Cluemore75;

@Clue0:
	Say("杨瑛：独孤大哥，我们先去客栈打听打听张姑娘和张少侠的消息。", 39);
	Return;

@Clue10:
	Say("杨瑛：这店小二怎有些怪怪的。", 39);
	Return;

@Clue15:
	Say("杨瑛：这里应该就是贺老四的家。", 39);
	Return;

@Clue20:
	Say("杨瑛：贺老四是天王帮在成都的接应人，虽然沉默少言，却是个精细人。", 39);
	Return;
	
@Clue25:
	Say("杨瑛：独孤大哥，真是奇怪，为什么客栈的掌柜和小二都说不知道呢？我觉得很可疑，现在去调查谁呢？", 39);
	Choose("独孤剑：我觉得应该查问……","A 店小二","B 吕掌柜", $Choose);
	If ($Choose == 0) @Choose250;
	If ($Choose == 1) @Choose251;
	
  @Choose250:	
	Say("杨瑛：我也觉得是，刚才这个小二就有点支支吾吾……如果独孤大哥想到什么线索，就马上跟我说！", 39);
	Return;
  @Choose251:
  	Say("杨瑛：这个吕掌柜倒也有些古怪，不过我觉得……独孤大哥，如果你想到什么线索，就马上跟我说。", 39);
	Return;
	
@Clue30:
	Say("杨瑛：既然已经知道张姑娘和张少侠的下落，我们不如在客栈休息一晚吧。", 39);
	Return;
	
@Clue31:
	Say("杨瑛：独孤大哥，我们现在去城北找张姑娘。", 39);
	Return;
	
@Clue35:
	Say("杨瑛：独孤大哥，我们现在去城北找张姑娘。", 39);
	Return;
	
@Clue40:
	Say("杨瑛：看来我们上当了……客栈的留书可能是假的。", 39);
	Return;

@Clue41:
	Say("杨瑛：独孤大哥，我觉得这里有些蹊跷……你认为谁最可疑？", 39);
	Choose("独孤剑：我怀疑……","A 贺老四","B 吕掌柜",$Choose);
	If ($Choose == 0) @Choose410;
	If ($Choose == 1) @Choose411;
	
  @Choose410:
  	Say("杨瑛：贺老四……他哪里可疑呢？", 39);
  	Choose("独孤剑：他的……","A 言语","B 表情",$Choose);
    	If ($Choose == 0) @Choose4100;
	If ($Choose == 1) @Choose4101;
    @Choose4100:
    	Say("杨瑛：言语？……对了！我扮成男装之事一般教众根本就不知道，而我换回女子装束也只是在刚刚离开总堂前。贺老四他如何一见到我们，便已知道我便是换回女装的帮主……", 42);
    	Say("独孤剑：而索七是最先离开总堂来到成都的帮中兄弟……", 1);
    	Say("杨瑛：他不可能在我们之前就见过贺老四，也就是说……", 42);
    	Say("独孤剑：贺老四一开始就知道杨姑娘的底细！", 6);
    	Say("杨瑛：对，我们快去找他！", 39);
    	Assign($Clue, 45);
    	Memo("独孤剑发现贺老四的破绽，两人决定调查贺老四。");
    	Return;
    @Choose4101:
    	Say("杨瑛：表情？……贺老四一贯寡言少语，其实为人很精明，是帮中的一个得力兄弟。", 39);
    	Say("独孤剑：看来，我们还得另找线索。", 9);
    	Say("杨瑛：独孤大哥，不必着急。如果你有什么发现，就告诉我。", 39);
    	Return;
  
  @Choose411:
  	Say("杨瑛：吕掌柜……他哪里可疑呢？", 39);
  	Choose("独孤剑：他的……","A 言语","B 表情",$Choose);
    	If ($Choose == 0) @Choose4110;
	If ($Choose == 1) @Choose4111;
    @Choose4110:
    	Say("杨瑛：贺老四说见过张姑娘在客栈投宿，可是这个吕掌柜却始终推说不知道。但他的话却没有什么矛盾之处啊……", 39);
    	Say("独孤剑：看来，我们得另想办法。", 9);
    	Say("杨瑛：独孤大哥，不必着急。如果你有什么发现，就告诉我。", 39);
    	Return;
    @Choose4111:
    	Say("杨瑛：吕掌柜神色确实有些古怪，不过倒是看不出什么破绽。店小二又莫名其妙的死了……", 39);
    	Say("独孤剑：我们应该留意这个吕掌柜。", 1);
    	Say("杨瑛：嗯。对了，独孤大哥，如果有什么发现，就告诉我。", 39);
    	Return;
    	
@Clue45:
	Say("杨瑛：独孤大哥，那我们快去找贺老四！", 39);
	Return;
	
@Clue46:
	Return;
	
@Clue50:
	Say("杨瑛：独孤大哥，我们在贺老四房间里搜一搜，也许能找到些线索。", 39);
	Return;
	
@Clue60:
	Say("杨瑛：“口”，独孤大哥，你认为这指的是什么呢？", 39);
	
